#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    const char *input = "";
    if (argc > 1) {
        input = argv[1];
    }
    size_t len = strlen(input);
    if (len > 1024) {
        puts("TOO_LONG");
        return 0;
    }
    // Normalize: keep only alphanumeric characters, case-insensitive (uppercase)
    char norm[1025]; // max length same as input length
    size_t n = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[n++] = (char)toupper(c);
        }
    }
    // Check palindrome
    int is_pal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }
    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
